<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const { onError } = this.props;
    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    onError?.(error, info);
  }

  retry = (): void => {
    this.setState({ error: null });
  };

  render(): ReactNode {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return <DefaultFallback error={error} retry={this.retry} />;
  }
}

function DefaultFallback({
  error,
  retry,
}: {
  error: Error;
  retry: () => void;
}) {
  return (
    <div
      role="alert"
      style={{
        padding: "24px",
        border: "1px solid #f87171",
        borderRadius: "8px",
        backgroundColor: "#fff1f2",
        fontFamily: "sans-serif",
        maxWidth: "480px",
        margin: "16px auto",
      }}
    >
      <h2 style={{ margin: "0 0 8px", color: "#b91c1c", fontSize: "1.1rem" }}>
        Something went wrong
      </h2>
      <p style={{ margin: "0 0 16px", color: "#374151", fontSize: "0.9rem" }}>
        {error.message}
      </p>
      <details
        style={{ marginBottom: "16px", fontSize: "0.8rem", color: "#6b7280" }}
      >
        <summary style={{ cursor: "pointer" }}>Stack trace</summary>
        <pre
          style={{
            marginTop: "8px",
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
          }}
        >
          {error.stack}
        </pre>
      </details>
      <button
        onClick={retry}
        style={{
          padding: "8px 16px",
          backgroundColor: "#b91c1c",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer",
          fontSize: "0.9rem",
        }}
      >
        Try again
      </button>
    </div>
  );
}
</parameter>
